44	/**
45	 * Mostly used as a facade for all Petclinic controllers
46	 * Also a placeholder for @Transactional and @Cacheable annotations
47	 *
48	 * @author Michael Isvy
49	 * @author Vitaliy Fedoriv
50	 */
51	@Service
52	public class ClinicServiceImpl implements ClinicService {
53	
54	    private final PetRepository petRepository;
55	    private final VetRepository vetRepository;
56	    private final OwnerRepository ownerRepository;
57	    private final VisitRepository visitRepository;
58	    private final SpecialtyRepository specialtyRepository;
59	    private final PetTypeRepository petTypeRepository;
60	
61	    public ClinicServiceImpl(
62	        PetRepository petRepository,
63	        VetRepository vetRepository,
64	        OwnerRepository ownerRepository,
65	        VisitRepository visitRepository,
66	        SpecialtyRepository specialtyRepository,
67	        PetTypeRepository petTypeRepository) {
68	        this.petRepository = petRepository;
69	        this.vetRepository = vetRepository;
70	        this.ownerRepository = ownerRepository;
71	        this.visitRepository = visitRepository;
72	        this.specialtyRepository = specialtyRepository;
73	        this.petTypeRepository = petTypeRepository;
74	    }
75	
76	    @Override
77	    @Transactional(readOnly = true)
78	    public Collection<Pet> findAllPets() throws DataAccessException {
79	        return petRepository.findAll();
80	    }
81	
82	    @Override
83	    @Transactional(readOnly = true)
84	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
85	        return petRepository.findAll(pageable);
86	    }
87	
88	    @Override
89	    @Transactional
90	    public void deletePet(Pet pet) throws DataAccessException {
91	        petRepository.delete(pet);
92	    }
93	
94	    @Override
95	    @Transactional(readOnly = true)
96	    public Visit findVisitById(int visitId) throws DataAccessException {
97	        return findEntityById(() -> visitRepository.findById(visitId));
98	    }
99	
100	    @Override
101	    @Transactional(readOnly = true)
102	    public Collection<Visit> findAllVisits() throws DataAccessException {
103	        return visitRepository.findAll();
104	    }
105	
106	    @Override
107	    @Transactional
108	    public void deleteVisit(Visit visit) throws DataAccessException {
109	        visitRepository.delete(visit);
110	    }
111	
112	    @Override
113	    @Transactional(readOnly = true)
114	    public Vet findVetById(int id) throws DataAccessException {
115	        return findEntityById(() -> vetRepository.findById(id));
116	    }
117	
118	    @Override
119	    @Transactional(readOnly = true)
120	    public Collection<Vet> findAllVets() throws DataAccessException {
121	        return vetRepository.findAll();
122	    }
123	
124	    @Override
125	    @Transactional
126	    public void saveVet(Vet vet) throws DataAccessException {
127	        vetRepository.save(vet);
128	    }
129	
130	    @Override
131	    @Transactional
132	    public void deleteVet(Vet vet) throws DataAccessException {
133	        vetRepository.delete(vet);
134	    }
135	
136	    @Override
137	    @Transactional(readOnly = true)
138	    public Collection<Owner> findAllOwners() throws DataAccessException {
139	        return ownerRepository.findAll();
140	    }
141	
142	    @Override
143	    @Transactional(readOnly = true)
144	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
145	        if (lastName != null) {
146	            return ownerRepository.findByLastName(lastName, pageable);
147	        }
148	        return ownerRepository.findAll(pageable);
149	    }
150	
151	    @Override
152	    @Transactional
153	    public void deleteOwner(Owner owner) throws DataAccessException {
154	        owner.setDeleted(true);
155	        ownerRepository.save(owner);
156	    }
157	
158	    @Override
159	    @Transactional(readOnly = true)
160	    public PetType findPetTypeById(int petTypeId) {
161	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
162	    }
163	
164	    @Override
165	    @Transactional(readOnly = true)
166	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
167	        return petTypeRepository.findAll();
168	    }
169	
170	    @Override
171	    @Transactional
172	    public void savePetType(PetType petType) throws DataAccessException {
173	        petTypeRepository.save(petType);
174	    }
175	
176	    @Override
177	    @Transactional
178	    public void deletePetType(PetType petType) throws DataAccessException {
179	        petTypeRepository.delete(petType);
180	    }
181	
182	    @Override
183	    @Transactional(readOnly = true)
184	    public Specialty findSpecialtyById(int specialtyId) {
185	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
186	    }
187	
188	    @Override
189	    @Transactional(readOnly = true)
190	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
191	        return specialtyRepository.findAll();
192	    }
193	
194	    @Override
195	    @Transactional
196	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
197	        specialtyRepository.save(specialty);
198	    }
199	
200	    @Override
201	    @Transactional
202	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
203	        specialtyRepository.delete(specialty);
204	    }
205	
206	    @Override
207	    @Transactional(readOnly = true)
208	    public Collection<PetType> findPetTypes() throws DataAccessException {
209	        return petRepository.findPetTypes();
210	    }
211	
212	    @Override
213	    @Transactional(readOnly = true)
214	    public Owner findOwnerById(int id) throws DataAccessException {
215	        return findEntityById(() -> ownerRepository.findById(id));
216	    }
217	
218	    @Override
219	    @Transactional(readOnly = true)
220	    public Pet findPetById(int id) throws DataAccessException {
221	        return findEntityById(() -> petRepository.findById(id));
222	    }
223	
224	    @Override
225	    @Transactional
226	    public void savePet(Pet pet) throws DataAccessException {
227	        pet.setType(findPetTypeById(pet.getType().getId()));
228	        petRepository.save(pet);
229	    }
230	
231	    @Override
232	    @Transactional
233	    public void saveVisit(Visit visit) throws DataAccessException {
234	        visitRepository.save(visit);
235	
236	    }
237	
238	    @Override
239	    @Transactional(readOnly = true)
240	    public Collection<Vet> findVets() throws DataAccessException {
241	        return vetRepository.findAll();
242	    }
243	
244	    @Override
245	    @Transactional
246	    public void saveOwner(Owner owner) throws DataAccessException {
247	        ownerRepository.save(owner);
248	
249	    }
250	
251	    @Override
252	    @Transactional
253	    public void createOwner(Owner owner) throws DataAccessException {
254	        rejectWhenDailyLimitReached(owner);
255	        rejectWhenCityAtCapacity(owner);
256	        owner.setHouseholdId(deriveHouseholdId(owner));
257	        List<Owner> householdMembers = findHouseholdMembers(owner);
258	        assignPossibleDuplicate(owner);
259	        owner.setHouseholdMemberCount(householdMembers.size() + 1);
260	        owner.setMembershipLevelCap(membershipLevelCap(householdMembers));
261	        if (owner.getCustomerCode() == null) {
262	            owner.setCustomerCode(deduplicateCustomerCode(deriveCustomerCode(owner)));
263	        }
264	        if (owner.getNamesakeCount() == null) {
265	            owner.setNamesakeCount(countNamesakes(owner));
266	        }
267	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
268	        ownerRepository.save(owner);
269	    }
270	
271	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
272	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
273	
274	    /**
275	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
276	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
277	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
278	     * today by the controller, determines which day is counted — the same accumulation path as the
279	     * daily-limit rule.
280	     */
281	    private boolean exceedsBulkSignupThreshold(Owner owner) {
282	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
283	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
284	    }
285	
286	    /**
287	     * Count the existing owners that already share this owner's first name and last name,
288	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
289	     * before the owner is persisted, so it reflects the owners present at creation time.
290	     */
291	    private int countNamesakes(Owner owner) {
292	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
293	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
294	        return (int) findActiveOwners().stream()
295	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
296	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
297	            .count();
298	    }
299	
300	    /**
301	     * The existing owners that have not been soft-deleted. Duplicate and identity checks run
302	     * against this set, so an owner flagged {@code deleted} (see {@link #deleteOwner(Owner)}) is
303	     * ignored and no longer blocks a create that would otherwise match it.
304	     */
305	    private List<Owner> findActiveOwners() {
306	        return ownerRepository.findAll().stream()
307	            .filter(existing -> !existing.isDeleted())
308	            .toList();
309	    }
310	
311	    /**
312	     * The existing owners that already belong to this owner's household, i.e. those carrying the
313	     * same deterministic {@code householdId} (see {@link #deriveHouseholdId(Owner)}). Because the
314	     * household id is derived purely from the normalized last name and postcode, this is exactly
315	     * the set of owners sharing that last name and postcode. Evaluated before the owner is
316	     * persisted, so it reflects the owners present at creation time. The owner's own
317	     * {@code householdId} must already be assigned before calling.
318	     */
319	    private List<Owner> findHouseholdMembers(Owner owner) {
320	        String householdId = owner.getHouseholdId();
321	        return findActiveOwners().stream()
322	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
323	            .toList();
324	    }
325	
326	    /**
327	     * Derive the owner's deterministic household identifier: the first twelve hexadecimal characters
328	     * of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}. Two owners with the
329	     * same last name (compared case-insensitively with collapsed whitespace) and postcode therefore
330	     * map to the same value automatically, without any opt-in, so they form one household.
331	     */
332	    private static String deriveHouseholdId(Owner owner) {
333	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
334	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
335	        return sha256HexPrefix(lastName + "|" + postcode, 12);
336	    }
337	
338	    /**
339	     * The membership-level ceiling for a new owner joining {@code householdMembers}: one above the
340	     * maximum membership level among the existing members. Returns {@code null} when the household
341	     * has no existing member, so no cap applies. Evaluated before the owner is persisted, so it
342	     * reflects the members (and their levels) present at creation time.
343	     */
344	    private Integer membershipLevelCap(List<Owner> householdMembers) {
345	        return householdMembers.stream()
346	            .map(MembershipLevels::level)
347	            .max(Integer::compareTo)
348	            .map(max -> max + 1)
349	            .orElse(null);
350	    }
351	
352	    /**
353	     * Set the new owner's soft-duplicate flags. A new owner joining an existing household is no
354	     * longer rejected as a duplicate — its membership level is capped instead (see
355	     * {@link #membershipLevelCap(List)}) — so the flags are always cleared here, but set explicitly
356	     * so the field is always present in the response. Evaluated before the owner is persisted.
357	     */
358	    private void assignPossibleDuplicate(Owner owner) {
359	        owner.setPossibleDuplicate(false);
360	        owner.setPossibleDuplicateOf(null);
361	    }
362	
363	    /** Maximum number of owners that may be created on any single day (by registration date). */
364	    private static final long DAILY_OWNER_LIMIT = 100L;
365	
366	    /**
367	     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
368	     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
369	     * reflects the owners present at creation time. The new owner's own registration date, defaulted
370	     * to today by the controller, determines which day the limit is checked against.
371	     */
372	    private void rejectWhenDailyLimitReached(Owner owner) {
373	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
374	        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
375	            throw new DailyOwnerLimitExceededException(
376	                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
377	        }
378	    }
379	
380	    /**
381	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
382	     * before the owner is persisted, so it reflects the owners present at creation time.
383	     */
384	    private long countOwnersRegisteredOn(LocalDate day) {
385	        return ownerRepository.findAll().stream()
386	            .filter(existing -> day.equals(existing.getRegistrationDate()))
387	            .count();
388	    }
389	
390	    /** Maximum number of owners allowed to live in any single city. */
391	    private static final long CITY_CAPACITY = 50L;
392	
393	    /**
394	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
395	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
396	     * is persisted, so it reflects the owners present at creation time.
397	     */
398	    private void rejectWhenCityAtCapacity(Owner owner) {
399	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
400	            throw new CityCapacityExceededException(
401	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
402	        }
403	    }
404	
405	    /**
406	     * Count the existing owners that already live in this owner's city, compared
407	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
408	     * owner is persisted, so it reflects the owners present at creation time.
409	     */
410	    private long countOwnersInCity(Owner owner) {
411	        String city = IdentityNormalizer.normalize(owner.getCity());
412	        return ownerRepository.findAll().stream()
413	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
414	            .count();
415	    }
416	
417	    /** Region-to-inclusive 4-digit postcode range {@code {low, high}}. */
418	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
419	        "NSW", new int[] {2000, 2099},
420	        "VIC", new int[] {3000, 3099},
421	        "QLD", new int[] {4000, 4099});
422	
423	    /** Region code used when the postcode maps to no known region (or is absent). */
424	    private static final String UNKNOWN_REGION = "UNKNOWN";
425	
426	    /**
427	     * Builds the customer code {@code '<REGION>-<HASH8>'}: the region code derived from the
428	     * owner's postcode, a hyphen, and the first eight upper-case hexadecimal characters of the
429	     * SHA-256 digest over the owner's normalized (E.164) telephone concatenated with the last
430	     * name. No sequence number is used; the identity is fully derived from the region and hash.
431	     */
432	    private String deriveCustomerCode(Owner owner) {
433	        String region = regionForPostcode(owner.getPostcode());
434	        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
435	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
436	        return region + "-" + sha256Hex8(telephone + lastName);
437	    }
438	
439	    /**
440	     * De-duplicates a computed {@code customerCode} against the existing owners: if no owner already
441	     * carries {@code baseCode} it is returned unchanged, otherwise {@code '-<n>'} is appended with the
442	     * smallest {@code n} of 2 or more that yields a value no existing owner holds. Evaluated before the
443	     * owner is persisted, so it reflects the owners present at creation time.
444	     */
445	    private String deduplicateCustomerCode(String baseCode) {
446	        Set<String> existingCodes = findActiveOwners().stream()
447	            .map(Owner::getCustomerCode)
448	            .filter(Objects::nonNull)
449	            .collect(Collectors.toSet());
450	        if (!existingCodes.contains(baseCode)) {
451	            return baseCode;
452	        }
453	        int n = 2;
454	        while (existingCodes.contains(baseCode + "-" + n)) {
455	            n++;
456	        }
457	        return baseCode + "-" + n;
458	    }
459	
460	    /**
461	     * Returns the region code whose inclusive postcode range contains {@code postcode}
462	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), or
463	     * {@code "UNKNOWN"} when the postcode is absent, not a 4-digit value, or in no known range.
464	     */
465	    private static String regionForPostcode(String postcode) {
466	        if (postcode == null || !postcode.matches("\\d{4}")) {
467	            return UNKNOWN_REGION;
468	        }
469	        int value = Integer.parseInt(postcode);
470	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
471	            int[] range = entry.getValue();
472	            if (value >= range[0] && value <= range[1]) {
473	                return entry.getKey();
474	            }
475	        }
476	        return UNKNOWN_REGION;
477	    }
478	
479	    /**
480	     * Returns the first eight upper-case hexadecimal characters (the first four bytes) of the
481	     * SHA-256 digest of the UTF-8 bytes of {@code value}.
482	     */
483	    private static String sha256Hex8(String value) {
484	        return sha256HexPrefix(value, 8).toUpperCase();
485	    }
486	
487	    /**
488	     * Returns the first {@code hexChars} lower-case hexadecimal characters of the SHA-256 digest of
489	     * the UTF-8 bytes of {@code value}.
490	     */
491	    private static String sha256HexPrefix(String value, int hexChars) {
492	        try {
493	            byte[] digest = MessageDigest.getInstance("SHA-256")
494	                .digest(value.getBytes(StandardCharsets.UTF_8));
495	            StringBuilder sb = new StringBuilder(hexChars);
496	            for (int i = 0; sb.length() < hexChars; i++) {
497	                sb.append(String.format("%02x", digest[i]));
498	            }
499	            return sb.substring(0, hexChars);
500	        }
501	        catch (NoSuchAlgorithmException e) {
502	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
503	        }
504	    }
505	
506	    @Override
507	    @Transactional(readOnly = true)
508	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
509	        return ownerRepository.findByLastName(lastName);
510	    }
511	
