17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Set;
20	import java.util.regex.Pattern;
21	
22	/**
23	 * Utility for normalizing the optional e-mail address submitted when creating or
24	 * updating an owner. A {@code null} value is left untouched (the field is optional),
25	 * but when a value is supplied it must be a syntactically valid address whose domain is
26	 * not on the disposable-domain blocklist; otherwise an {@link InvalidEmailException} is
27	 * raised so the request is rejected with {@code 400 Bad Request}. Valid values are
28	 * returned lower-cased for consistent storage and retrieval.
29	 */
30	public final class EmailNormalizer {
31	
32	    /**
33	     * Pragmatic syntactic check for an e-mail address: a non-empty local part, a single
34	     * {@code @}, and a dotted domain whose top-level label is alphabetic.
35	     */
36	    private static final Pattern EMAIL_PATTERN =
37	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
38	
39	    /**
40	     * Domains of disposable / throwaway e-mail providers that are not accepted for an owner.
41	     */
42	    private static final Set<String> DISPOSABLE_DOMAINS =
43	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
44	
45	    private EmailNormalizer() {
46	    }
47	
48	    /**
49	     * Normalize the supplied e-mail address.
50	     *
51	     * @param email the raw e-mail value (may be {@code null} because the field is optional)
52	     * @return {@code null} when the input is {@code null}, otherwise the address lower-cased
53	     * @throws InvalidEmailException if a value is supplied but is not syntactically valid,
54	     *     or its domain is on the disposable-domain blocklist
55	     */
56	    public static String normalize(String email) {
57	        if (email == null) {
58	            return null;
59	        }
60	        if (!EMAIL_PATTERN.matcher(email).matches()) {
61	            throw new InvalidEmailException("email must be a syntactically valid address");
62	        }
63	        String normalized = email.toLowerCase();
64	        String domain = normalized.substring(normalized.indexOf('@') + 1);
65	        if (DISPOSABLE_DOMAINS.contains(domain)) {
66	            throw new InvalidEmailException("email domain is not accepted");
67	        }
68	        return normalized;
69	    }
70	}
